DispatchBitmaskHandlers:
	dec 2, xsp
	push xiz
	ld xiz, xbc
	ld (xsp + 4), wa
	cpw (xiz), 0xffff
	jr z, BitmaskDispatch_Return

; Bitmask dispatch loop handler
BitmaskDispatch_LoopHandler:
	ld wa, (xsp + 4)
	and wa, (xiz)
	jr z, BitmaskDispatch_NextEntry
	ld xhl, (xiz + 2)
	call (xhl)

BitmaskDispatch_NextEntry:
	inc 6, xiz
	cpw (xiz), 0xffff
	jr nz, BitmaskDispatch_LoopHandler

BitmaskDispatch_Return:
	pop xiz
	inc 2, xsp
	ret


; This routine seems to set the LEDs of the control panel
; I'm not sure yet if this is initialization, or if it
; also serves to update the LEDs later on.
CtrlPanel_UpdateLEDState:
	.byte 0xef, 0x68, 0xd7, 0xfa, 0x04, 0xf1, 0x7c, 0x8e
	.byte 0x30, 0xbf, 0x02, 0x60, 0xf1, 0x8c, 0x8e, 0x30
	.byte 0xbf, 0x06, 0x60, 0xc1, 0x9a, 0x8c, 0x3f, 0xf7
	.byte 0x66, 0x41, 0xc7, 0xfb, 0xa8
LEDUpdate_ProcessChannel:
	stb_erp A, 0xfb
	extz wa
	ld xbc, (xsp + 2)
	ldb_sri C, 0x07, 0xe4, 0xe0
	ldb_erp C, 0xfa
	ld xbc, (xsp + 6)
	ldb_sri C, 0x07, 0xe4, 0xe0
	cpb_erp C, 0xfa
	jr z, LEDUpdate_NextChannel
	stb_erp C, 0xfa
	extz bc
	calr Set_LEDs
	stb_erp E, 0xfb
	extz de
	ld xwa, (xsp + 6)
	stb_erp C, 0xfa
	lda_dri XHL, 0x07, 0xe0, 0xe8

LEDUpdate_NextChannel:
	inc1b_erp 0xfb
	cp_erpb 0xfb, 0x0f
	jr c, LEDUpdate_ProcessChannel

LEDUpdate_Cleanup:
	popw_erp 0xfa
	inc 8, xsp
	ret


Set_LEDs:
	.byte 0xc9, 0x8d, 0xcd, 0xcf, 0x0f, 0xb0, 0xfb, 0xf1
	.byte 0x9c, 0x8e, 0x30, 0xda, 0x12, 0xf2, 0x16, 0xa6
