	.byte 0x45, 0xb8, 0x01, 0x43, 0x1e, 0x01, 0x00, 0x0e
LED_WriteToPanel:
	push xiz
	ld xiz, xwa
	ld a, (xiz)
	extz wa
	pushw wa
	call Seq_TimerEventLoop
	inc 2, xsp
	cp hl, 0xffff
	jr nz, LED_WriteSecondByte
	push xde
	push xhl
	push xix
	push xiz
	call CPanel_Poll
	pop xiz
	pop xix
	pop xhl
	pop xde
	ld xwa, xiz
	jr LED_WriteThirdByte

LED_WriteSecondByte:
	ld a, (xiz + 1)
	extz wa
	pushw wa
	call Seq_TimerEventLoop
	inc 2, xsp
	cp hl, 0xffff
	jr nz, LED_WriteDone
	push xde
	push xhl
	push xix
	push xiz
	call CPanel_Poll
	pop xiz
	pop xix
	pop xhl
	pop xde
	lda xwa, (xiz + 1)

LED_WriteThirdByte:
	ld a, (xwa)
	extz wa
	pushw wa
	call Seq_TimerEventLoop
	inc 2, xsp

LED_WriteDone:
	pop xiz
	ret


